        position: 'fixed',
        zIndex: 60,
        pointerEvents: 'auto',
        touchAction: 'none',
        userSelect: 'none',
        cursor: dragging ? 'grabbing' : 'grab',
        left: (roam ? roam.x : layout.x) + 'px',
        top: layout.y + 'px',
        transition: roam && roam.ms ? ('left ' + roam.ms + 'ms ' + (roam.ease || 'linear')) : 'none',
